    _prepareSuccessCallback: function(callback, closeSuccess) {
        var wnd = this;
        callback = core.nullValue(callback, {});
        var success = core.nullValue(callback.success, {});
        var failure = core.nullValue(callback.failure, {});
        callback = core.nullValue(callback, {});

        function restoreCallbacks() {
            callback.success = success;
            callback.failure = failure;
        }

        function copyFocusesOn(out_scope, args){
            return Ext.Ajax.request({
                url: toolkit.util.Normalize.controller_action('GFPConfigEvent', 'copy_old_incide'),
                params: {
                    new_event: args.pk,
                    old_event: out_scope.values.old_events
                },
                scope: out_scope,
                callback: function() {

                },
                success: function(request) {
                    var obj = Ext.decode(request.responseText);
                    if(!obj.success)
                        Ext.Msg.show({
                            title: out_scope.title,
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK,
                            msg: obj.message
                        });
                },
                failure: function(request) {
                    Ext.Msg.show({
                        title: out_scope.title,
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                        msg: 'Não foi possível copiar os eventos de "incide sobre"'
                    });
                }
            });
        }

        if(this.saveAndContinue === undefined || this.saveAndContinue === false) {
            callback.success = {
                fn: function(args) {
                    core.invokeCallback(
                        (success || {fn: Ext.emptyFn}),
                        args
                    );
                    // copia incide sobre do config copiado
                    if(wnd.getFocusesTrue() && wnd.getFocusesTrue().getValue()==true){
                        copyFocusesOn(wnd, args);
                    }

                    if(closeSuccess)
                        wnd.destroy();
                    else
                        wnd.resetForm();

                    restoreCallbacks();
                }
            };
        }
        else {
            callback.success = {
                fn: function(args) {
                    core.invokeCallback(
                        (success || {fn: Ext.emptyFn}),
                        args
                    );

                    // copia incide sobre do config copiado
                    if(wnd.getFocusesTrue() && wnd.getFocusesTrue().getValue()==true){
                        copyFocusesOn(wnd, args);
                    }

                    if(closeSuccess)
                        core.invokeCallback(
                            (wnd.saveAndContinue || {fn: Ext.emptyFn}),
                            args
                        );
                    else {
                        wnd.action = 'create';
                        wnd.oId = null;
                        wnd.resetForm();
                    }

                    restoreCallbacks();
                }
            };
        }

        callback.failure = rh.gfp.payroll.ConfigEventWindow.superclass._prepareSuccessCallback.call(this, callback, closeSuccess).failure

        return callback;
    },

